#include <stddef.h>

void reverseArray(int[] arr, int n) {
    int n = arr.length;
    int start = 0;
    int end = 0;

    while (start <= n) {
        if (arr[start] == arr[end]) {
            start += 1;
            arr[start] = arr[end];
        } else {
            end--;
        }
    }

    return start;
}

